<script setup>
import { ref, computed, onMounted, onBeforeUnmount, h, nextTick, watch } from 'vue'
import FishGlyph from './FishGlyph.vue'
import { fishChineseName } from './fish-labels.js'

const paths={home:['M3 10 12 3l9 7','M5 9v12h14V9','M9 21v-8h6v8'],data:['M12 3c5 0 9 2 9 4s-4 4-9 4-9-2-9-4 4-4 9-4Z','M3 7v10c0 2 4 4 9 4s9-2 9-4V7','M3 12c0 2 4 4 9 4s9-2 9-4'],train:['M4 20V10','M10 20V4','M16 20v-7','M22 20V7','M2 20h22'],scan:['M8 3H4a1 1 0 0 0-1 1v4','M16 3h4a1 1 0 0 1 1 1v4','M21 16v4a1 1 0 0 1-1 1h-4','M8 21H4a1 1 0 0 1-1-1v-4','M8 12c2-4 6-4 8 0-2 4-6 4-8 0Z'],chart:['M3 3v18h18','m7 14 4-5 4 3 5-8'],chat:['M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 1 1 19 0Z','M7 10h.01','M12 10h.01','M17 10h.01'],arrow:['M4 12h16','m14 6 6 6-6 6'],upload:['M12 16V3','m7 8 5-5 5 5','M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4'],check:['m5 12 4 4L19 6'],clock:['M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18','M12 7v5l3 2'],help:['M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18','M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4','M12 17h.01'],link:['M14 3h7v7','m10 14 11-11','M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5'],close:['m6 6 12 12','M6 18 18 6'],play:['m9 5 11 7-11 7V5Z'],fish:['M3 12c4-8 12-8 17 0-5 8-13 8-17 0Z','m3 12-2-5v10l2-5','M15 10h.01'],spark:['m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z'],download:['M12 3v13','m7 11 5 5 5-5','M4 17v4h16v-4'],refresh:['M20 7a9 9 0 1 0 1 7','M20 2v5h-5'],folder:['M3 6h7l2 3h9v12H3V6Z'],menu:['M3 6h18','M3 12h18','M3 18h18']}
const Icon=({name,size=20})=>h('svg',{viewBox:'0 0 24 24',width:size,height:size,fill:'none',stroke:'currentColor','stroke-width':1.65,'stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true'},(paths[name]||paths.fish).map(d=>h('path',{d})))
const nav=[{id:'overview',label:'项目介绍',en:'Overview',icon:'home'},{id:'data',label:'数据理解',en:'Dataset',icon:'data'},{id:'training',label:'模型训练',en:'Training',icon:'train'},{id:'inference',label:'模型推理',en:'Inference',icon:'scan'},{id:'dashboard',label:'监控仪表盘',en:'Dashboard',icon:'chart'},{id:'assistant',label:'智能助手',en:'Assistant',icon:'chat'}]
const page=ref(location.hash.slice(1)||'overview'),guide=ref(false)
if(!nav.some(n=>n.id===page.value))page.value='overview'
function go(id){page.value=id;location.hash=id;window.scrollTo({top:0,behavior:'smooth'})}
function revealCurrentPage(){const navigation=document.querySelector('.top-nav'),active=navigation?.querySelector('[aria-current="page"]');if(navigation&&active&&navigation.scrollWidth>navigation.clientWidth){const left=active.getBoundingClientRect().left-navigation.getBoundingClientRect().left+navigation.scrollLeft-(navigation.clientWidth-active.clientWidth)/2;navigation.scrollTo({left,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}}
watch(page,()=>nextTick(revealCurrentPage))
onMounted(()=>{nextTick(revealCurrentPage);window.addEventListener('resize',revealCurrentPage)})
onBeforeUnmount(()=>window.removeEventListener('resize',revealCurrentPage))
const current=computed(()=>nav.find(n=>n.id===page.value)||nav[0])
const status=ref(null), dataset=ref(null), experiments=ref(null), jobs=ref([]), apiError=ref(''), notice=ref(''), busy=ref(false)
const documentedClasses='Batashi Bele Chanda Chapila Chela Foli Ilish Kajuli Kayakanta Koi Magur Mola Mrigel Pabda Pangas Puti Rui Rupchada Shol Sorputi Taki Tarabaim Telapia Tengra Veda Vetki ayer boyal chitol kalbaus katol kholshe shing'.split(' ')
const classes=computed(()=>dataset.value?.classes||documentedClasses.map((name,id)=>({id,name})))
const classSearch=ref(''), filteredClasses=computed(()=>{const q=classSearch.value.trim().toLowerCase();return classes.value.filter(c=>String(c.name).toLowerCase().includes(q)||fishChineseName(c.name).toLowerCase().includes(q))})
const models=computed(()=>status.value?.models||[]), fishModels=computed(()=>models.value.filter(m=>m.kind==='fish'))
const counts=computed(()=>dataset.value?.counts||{total:4560,instances:6034,train:3652,val:458,test:450})
const localReady=computed(()=>Boolean(dataset.value?.local?.available)), engineReady=computed(()=>Boolean(status.value?.engine?.available))
const formatNum=n=>Number(n||0).toLocaleString('zh-CN')
const monitor=ref(null),monitorError=ref(''),monitorBusy=ref(false),lastMonitorSample=ref('')
let monitorTimer=null
const percentText=value=>value==null||!Number.isFinite(Number(value))?'—':Number(value).toFixed(1)
const safePercent=value=>value==null?0:Math.min(100,Math.max(0,Number(value)||0))
const memoryText=value=>value==null?'—':(Number(value)/1024**3).toFixed(2)+' GB'
const processMemoryText=value=>value==null?'—':(Number(value)/1024**2).toFixed(1)+' MB'
function uptimeText(value){if(value==null)return '—';const n=Math.max(0,Math.floor(Number(value)));return n>=3600?`${Math.floor(n/3600)} 小时 ${Math.floor(n%3600/60)} 分钟`:n>=60?`${Math.floor(n/60)} 分钟 ${n%60} 秒`:`${n} 秒`}
async function refreshMonitor(){if(page.value!=='dashboard'||document.hidden||monitorBusy.value)return;monitorBusy.value=true;try{const result=await request('/api/monitor/');monitor.value=result;monitorError.value='';lastMonitorSample.value=result.sampled_at||''}catch(e){monitor.value=null;monitorError.value='实时监控连接中断，当前无法获取本机读数。请检查本地服务后刷新。'}finally{monitorBusy.value=false}}
function syncMonitorPolling(){clearInterval(monitorTimer);monitorTimer=null;if(page.value==='dashboard'&&!document.hidden){refreshMonitor();monitorTimer=setInterval(refreshMonitor,5000)}}

async function request(url,options={}){const r=await fetch(url,{...options,headers:options.body instanceof FormData?{}:{'Content-Type':'application/json',...options.headers}});let d;try{d=await r.json()}catch{throw new Error('服务未返回有效数据，请检查后端是否启动。')}if(!r.ok)throw new Error(d.message||d.error?.message||d.error||d.detail||'请求失败');return d}
async function refresh(){apiError.value='';const rs=await Promise.allSettled([request('/api/status/'),request('/api/dataset/'),request('/api/experiments/'),request('/api/jobs/')]);if(rs[0].status==='fulfilled')status.value=rs[0].value;else apiError.value='本地服务暂未连接，当前展示仓库文档信息。请启动 Django 后端。';if(rs[1].status==='fulfilled')dataset.value=rs[1].value;if(rs[2].status==='fulfilled')experiments.value=rs[2].value;if(rs[3].status==='fulfilled')jobs.value=rs[3].value.jobs||rs[3].value.results||[];if(!inferForm.value.model&&fishModels.value.length)inferForm.value.model=fishModels.value[0].id;if(!trainForm.value.model&&models.value.length)trainForm.value.model=models.value[0].id;if(page.value==='dashboard')await refreshMonitor()}
const trainForm=ref({type:'train',model:'',epochs:10,batch:8,imgsz:512,device:'cpu'}),trainJob=ref(null),trainError=ref('')
const inferForm=ref({model:'',conf:.4,iou:.7,imgsz:512,device:'cpu',stride:1}),file=ref(null),filePreview=ref(''),fileInput=ref(null),dragging=ref(false),inferJob=ref(null),inferError=ref('')
const activeJob=computed(()=>inferJob.value||trainJob.value), completedJobs=computed(()=>jobs.value.filter(j=>['completed','succeeded','success'].includes(j.status)))
const running=s=>['queued','pending','running'].includes(s), statusText=s=>({queued:'等待运行',pending:'等待运行',running:'正在处理',completed:'已完成',succeeded:'已完成',success:'已完成',failed:'运行失败',cancelled:'已取消',interrupted:'运行中断'}[s]||s)
let pollTimer
async function pollJob(id,kind){try{const j=await request(`/api/jobs/${id}/`);if(kind==='train')trainJob.value=j;else inferJob.value=j;const existing=jobs.value.findIndex(x=>x.id===id);if(existing>=0)jobs.value.splice(existing,1,j);else jobs.value.unshift(j);if(running(j.status))pollTimer=setTimeout(()=>pollJob(id,kind),1500);else if(kind==='train')refresh()}catch(e){if(kind==='train')trainError.value=e.message;else inferError.value=e.message}}
async function startTrain(){trainError.value='';busy.value=true;try{const j=await request('/api/jobs/',{method:'POST',body:JSON.stringify(trainForm.value)});trainJob.value=j;pollJob(j.id,'train')}catch(e){trainError.value=e.message}finally{busy.value=false}}
async function cancelJob(job){try{await request(`/api/jobs/${job.id}/cancel/`,{method:'POST',body:'{}'});await pollJob(job.id,job.type==='train'?'train':'infer')}catch(e){notice.value=e.message}}
function chooseFile(f){if(!f)return;if(!/\.(mp4|mov|avi|mkv|webm|jpg|jpeg|png|webp)$/i.test(f.name)){inferError.value='请选择 MP4、MOV、AVI、MKV、WebM 视频或 JPG、PNG、WebP 图片。';return}if(f.size>250*1024*1024){inferError.value='文件超过 250 MB，请先裁剪视频。';return}if(filePreview.value)URL.revokeObjectURL(filePreview.value);file.value=f;filePreview.value=URL.createObjectURL(f);inferError.value=''}
async function startInfer(){inferError.value='';busy.value=true;try{const form=new FormData();form.append('file',file.value);Object.entries(inferForm.value).forEach(([k,v])=>form.append(k,v));const j=await request('/api/inference/',{method:'POST',body:form});inferJob.value=j;pollJob(j.id,'infer')}catch(e){inferError.value=e.message}finally{busy.value=false}}
const fileIsVideo=computed(()=>file.value&&(/\.(mp4|mov|avi|mkv|webm)$/i.test(file.value.name)))
const inferResult=computed(()=>inferJob.value?.result),resultMedia=computed(()=>inferResult.value?.media_url||inferResult.value?.output_url||inferResult.value?.annotated_url||inferResult.value?.video_url||inferResult.value?.image_url)
const resultCounts=computed(()=>{const c=inferResult.value?.class_counts||inferResult.value?.summary?.class_counts||{};return Array.isArray(c)?c.map(x=>({...x,name:x.name||x.label})):Object.entries(c).map(([name,count])=>({name,count}))})
function downloadReport(){if(!inferJob.value)return;const b=new Blob([JSON.stringify(inferResult.value||inferJob.value,null,2)],{type:'application/json'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=`fishscope-${inferJob.value.id}.json`;a.click();URL.revokeObjectURL(u)}
const messages=ref([{role:'assistant',content:'你好，我是渔见助手。你可以问我数据集、训练指标或检测流程；完成一次本地推理后，我还能结合检测证据解释结果。'}]), question=ref(''),chatBusy=ref(false),chatMode=ref(null),chatError=ref('')
const messageList=ref(null)
watch(()=>[messages.value.length,chatBusy.value],async()=>{await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight})
const prompts=['这个项目可以做什么？','mAP50 和置信度有什么区别？','视频检测数量代表鱼的个体数吗？','如何提高鱼类检测效果？']
async function sendChat(text){const msg=(text||question.value).trim();if(!msg||chatBusy.value)return;question.value='';chatError.value='';const history=messages.value.slice(-10).map(m=>({role:m.role,content:m.content}));messages.value.push({role:'user',content:msg});chatBusy.value=true;try{const d=await request('/api/chat/',{method:'POST',body:JSON.stringify({message:msg,job_id:inferResult.value?inferJob.value.id:undefined,history})});messages.value.push({role:'assistant',content:d.answer,mode:d.mode,disclosure:d.disclosure});chatMode.value=d.mode}catch(e){chatError.value=e.message}finally{chatBusy.value=false}}
function explain(){go('assistant');sendChat('请根据这次本地 YOLO 推理的真实证据，解释识别到的鱼类、置信度、数量统计口径和局限。')}
const actualExperiments=computed(()=>experiments.value?.experiments||[])
const trainingRun=computed(()=>experiments.value?.training_summary||null)
const trainingCurves=computed(()=>trainingRun.value?.curves||[])
const trainingPercent=value=>value==null?'—':(Number(value)*100).toFixed(2)+'%'
function curvePoints(key){const rows=trainingCurves.value;const last=Math.max(...rows.map(r=>Number(r.epoch)),2);return rows.filter(r=>Number.isFinite(Number(r[key]))).map(r=>`${44+(Number(r.epoch)-1)/(last-1)*560},${195-Math.min(1,Math.max(0,Number(r[key])))*155}`).join(' ')}
function experimentMetric(e,key){const aliases={map50:'metrics/mAP50(B)',map50_95:'metrics/mAP50-95(B)',precision:'metrics/precision(B)',recall:'metrics/recall(B)'};return trainingPercent(e.metrics?.[key]??e.metrics?.[aliases[key]])}
const dateText=t=>t?new Date(t).toLocaleString('zh-CN',{hour12:false}):'—'
onMounted(()=>{refresh();window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(nav.some(n=>n.id===p))page.value=p})})
onBeforeUnmount(()=>{clearTimeout(pollTimer);if(filePreview.value)URL.revokeObjectURL(filePreview.value)})
watch(page,syncMonitorPolling)
onMounted(()=>{syncMonitorPolling();document.addEventListener('visibilitychange',syncMonitorPolling)})
onBeforeUnmount(()=>{clearInterval(monitorTimer);document.removeEventListener('visibilitychange',syncMonitorPolling)})
</script>

<template>
  <div class="app-shell aquatic-shell">
    <div class="water-decor" aria-hidden="true"><div class="water-bubbles"><i v-for="n in 6" :key="n"></i></div><img class="decor-fish" src="/images/fish-school.svg" alt="" /></div>
    <header class="site-header">
      <div class="header-inner">
        <a href="#overview" class="brand" @click.prevent="go('overview')"><span class="brand-symbol"><Icon name="fish" :size="32" /></span><span><b>渔见<span class="brand-dot">.</span></b></span></a>
        <nav class="top-nav" aria-label="主要导航"><button v-for="item in nav" :key="item.id" class="nav-tab" :class="{active:page===item.id}" :aria-current="page===item.id?'page':undefined" @click="go(item.id)"><Icon :name="item.icon" :size="18" /><span>{{ item.label }}<small>{{ item.en }}</small></span><span v-if="item.id==='assistant'" class="ai-label">AI</span></button></nav>
        <div class="header-actions"><span class="workspace-pill"><i :class="status?'ready':'wait'"></i>{{ status?'本地已连接':'连接中' }}</span><button class="guide-trigger" @click="guide=true"><Icon name="help" :size="17" /><span>使用指南</span></button></div>
      </div>
    </header>
    <div class="main-shell water-workspace">
      <div class="topbar"><div class="breadcrumb"><Icon name="fish" :size="16" /><span>工作空间</span><span class="crumb-slash">/</span><b>{{ current.label }}</b></div><div class="top-actions"><span class="local-pill"><i></i> 本地部署</span><a href="https://github.com/chenkangkang999/-ODPlatform2" target="_blank" rel="noopener" class="repo-link">GitHub <Icon name="link" :size="14" /></a><button class="avatar" title="项目工作空间" @click="guide=true">鱼</button></div></div>
      <main>
        <div v-if="apiError" class="notice warning"><Icon name="help" :size="17" />{{ apiError }}<button @click="refresh">重新连接</button></div>
        <div v-if="notice" class="notice"><span>{{ notice }}</span><button @click="notice=''">关闭</button></div>

        <section v-if="page==='overview'" class="page overview-page">
          <div class="page-title"><div><div class="eyebrow">A CLEARER VIEW BELOW THE SURFACE</div><h1>探索水下世界，<span>从识别开始。</span></h1><p>从一张图片到一段视频，用计算机视觉读懂淡水鱼。</p></div><div class="version-tag">ODPLATFORM <span>2.0</span></div></div>
          <div class="hero-grid"><div class="hero"><div class="hero-water"></div><img src="/images/fish-hero-v2.png" alt="AI生成的蓝色淡水鱼场景，仅作项目展示" class="hero-photo"><div class="hero-gradient"></div><div class="hero-copy"><span class="hero-tag"><i></i> 淡水鱼智能检测与解释平台</span><h2>看见鱼群，<br>读懂<span>水下</span>。</h2><p>从图片到视频，探索淡水鱼的多样世界。<br>让每一次检测，都有清晰的解释。</p><button class="button button-mint" @click="go('inference')"><Icon name="scan" :size="18" /> 开始智能识别 <Icon name="arrow" :size="18" /></button></div><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div></div>
          <div class="quick-panel"><div class="card-eyebrow">WORKSPACE STATUS <span class="live-dot"></span></div><h3>研究，从这里继续</h3><p class="muted">每一步状态，真实可见。</p><div class="status-list"><div><span><Icon name="data" :size="17" /> 业务数据集</span><b :class="localReady?'state-ready':'state-wait'">{{ localReady?'已接入':'待接入' }}</b></div><div><span><Icon name="fish" :size="17" /> 本地候选权重</span><b :class="fishModels.length?'state-ready':'state-wait'">{{ fishModels.length?'待核验':'待接入' }}</b></div><div><span><Icon name="spark" :size="17" /> 大模型服务</span><b :class="status?.llm?.configured?'state-ready':'state-neutral'">{{ status?.llm?.configured?'已配置':'本地解释' }}</b></div></div><div class="quick-bottom"><span>首次使用？</span><button @click="guide=true">查看接入指南 <Icon name="arrow" :size="14" /></button></div></div></div>
          <div class="metric-grid"><article class="metric-card"><span class="metric-icon teal"><Icon name="fish" /></span><div><span>淡水鱼类别</span><strong>33<small>类</small></strong></div><span class="metric-foot">BengalDeltaFish</span></article><article class="metric-card"><span class="metric-icon blue"><Icon name="data" /></span><div><span>标注图像</span><strong>4,560<small>张</small></strong></div><span class="metric-foot">6,034 个标注实例</span></article><article class="metric-card"><span class="metric-icon amber"><Icon name="chart" /></span><div><span>mAP@50</span><strong>90.73<small>%</small></strong></div><span class="metric-foot">仓库独立验证集评估记录</span></article><article class="metric-card"><span class="metric-icon violet"><Icon name="check" /></span><div><span>数据质量检查</span><strong>15<small>/ 15</small></strong></div><span class="metric-foot">仓库记录 · 全部通过</span></article></div>
          <div class="section-heading"><div><span class="eyebrow">FROM DATA TO DISCOVERY</span><h2>一条完整的视觉研究链路</h2></div><button class="text-button" @click="go('dashboard')">查看仪表盘 <Icon name="arrow" :size="17" /></button></div>
          <div class="workflow"><button v-for="(step,i) in nav.slice(1,5)" :key="step.id" @click="go(step.id)"><span class="workflow-no">0{{ i+1 }}</span><span class="workflow-icon"><Icon :name="step.icon" :size="25" /></span><h3>{{ step.label }}</h3><p>{{ ['了解样本分布与划分契约','配置参数，启动真实训练','上传图片或视频，本地识别','追踪指标、任务和运行结果'][i] }}</p><Icon class="workflow-arrow" name="arrow" :size="18" /></button></div>
          <div class="home-bottom"><div class="insight-card"><div class="insight-icon"><Icon name="spark" :size="28" /></div><div><span class="eyebrow">BEYOND DETECTION</span><h3>让检测结果，也有清晰的解释。</h3><p>向助手提问，或把一次识别交给它分析。解释依据来自结构化检测证据。</p></div><button class="button button-light" @click="go('assistant')">与助手对话 <Icon name="arrow" :size="16" /></button></div><a class="gradio-card" :href="status?.gradio?.url||'http://127.0.0.1:7860'" target="_blank" rel="noopener"><span class="gradio-mark">G</span><div><h3>Gradio 演示</h3><p>轻量体验 · 需单独启动</p></div><Icon name="link" :size="17" /></a></div>

        </section>

        <section v-else-if="page==='data'" class="page"><div class="page-title"><div><div class="eyebrow">KNOW YOUR DATA</div><h1>数据理解<span> / Dataset</span></h1><p>从数据分布出发，理解模型看到的世界。</p></div><span class="badge">YOLO FORMAT</span></div><div class="data-banner"><div><span class="eyebrow">BENGAL DELTA FISH</span><h2>33 种淡水鱼，一个统一的检测数据集。</h2></div><Icon name="fish" :size="86" /></div><div class="metric-grid three"><article class="plain-metric"><span>图像总数</span><strong>{{ formatNum(counts.total) }}</strong><small>仓库文档记录</small></article><article class="plain-metric"><span>标注实例</span><strong>{{ formatNum(counts.instances) }}</strong><small>图中鱼体的边界框</small></article><article class="plain-metric"><span>本机数据集</span><strong class="small-value">{{ localReady?'已接入':'等待接入' }}</strong><small>{{ localReady?'可启动本地训练':'在 data/processed/fish 放入真实数据' }}</small></article></div><div class="two-col"><article class="card"><div class="card-head"><div><span class="eyebrow">FROZEN SPLIT · SEED 42</span><h3>数据集划分</h3></div><span class="badge">分层多标签</span></div><div class="split-chart"><div class="donut"><span><b>4,560</b><small>图像样本</small></span></div><div class="chart-legend"><div v-for="(n,i) in [{label:'训练集',n:3652,p:'80.1%',c:'var(--teal)'},{label:'验证集',n:458,p:'10.0%',c:'#8ebbb5'},{label:'测试集',n:450,p:'9.9%',c:'#e5bf7a'}]" :key="i"><i :style="{background:n.c}"></i><span>{{ n.label }}</span><b>{{ formatNum(n.n) }}</b><small>{{ n.p }}</small></div></div></div></article><article class="card"><div class="card-head"><div><span class="eyebrow">QUALITY & PROVENANCE</span><h3>可追溯的数据链路</h3></div><Icon name="check" /></div><div class="quality-step"><span>01</span><div><b>原始数据转换</b><p>统一 VOC / COCO / YOLO 数据格式</p></div></div><div class="quality-step"><span>02</span><div><b>15 项数据质量检查</b><p>标签、类别、边界框与划分完整性校验</p></div></div><div class="quality-step"><span>03</span><div><b>指纹与审计快照</b><p>记录数据身份，训练前核验来源</p></div></div></article></div><article class="card"><div class="card-head"><div><span class="eyebrow">CLASS DICTIONARY</span><h3>类别字典 <small>33 类</small></h3></div><input class="search-input" v-model="classSearch" placeholder="搜索类别名称…" aria-label="搜索鱼类" /></div><div class="class-grid"><div v-for="c in filteredClasses" :key="c.id"><FishGlyph :variant="c.id" :size="40" /><span class="class-labels"><b>{{ c.name }}</b><small>{{ fishChineseName(c.name) }}</small></span></div></div><p v-if="!filteredClasses.length" class="empty-small">没有匹配的鱼类。</p></article></section>

        <section v-else-if="page==='training'" class="page"><div class="page-title"><div><div class="eyebrow">TEACH THE MODEL TO SEE</div><h1>模型训练<span> / Training</span></h1><p>配置一次可复现的训练，让每一步都有记录。</p></div><span class="badge">YOLO11 · LOCAL</span></div><div class="notice" :class="{'warning':!localReady}"><Icon :name="localReady?'check':'folder'" :size="18" /><span>{{ localReady?'本机鱼类数据集已就绪。':'本机尚未接入鱼类训练数据。请先准备 data/processed/fish 与数据配置。' }}</span><button @click="go('data')">查看数据</button></div><div class="two-col training-layout"><form class="card" @submit.prevent="startTrain"><div class="card-head"><div><span class="eyebrow">NEW EXPERIMENT</span><h3>创建训练任务</h3></div><Icon name="train" /></div><label>业务数据集<select disabled><option>BengalDeltaFish · fish / 33 类</option></select></label><label>起始权重<select v-model="trainForm.model" required><option value="" disabled>选择本机已登记的模型权重</option><option v-for="m in models" :value="m.id" :key="m.id">{{ m.name }}</option></select></label><div class="form-row"><label>训练轮数 Epochs<input v-model.number="trainForm.epochs" type="number" min="1" max="1000" required /></label><label>批大小 Batch<input v-model.number="trainForm.batch" type="number" min="1" max="128" required /></label></div><div class="form-row"><label>输入尺寸<select v-model.number="trainForm.imgsz"><option :value="320">320 × 320</option><option :value="512">512 × 512</option><option :value="640">640 × 640</option><option :value="960">960 × 960</option></select></label><label>运行设备<select v-model="trainForm.device"><option value="cpu">CPU</option><option value="0">GPU 0 · 需 CUDA</option></select></label></div><p class="muted small">点击后将在本机启动平台训练命令，执行数据身份核验、训练、归档与审计。</p><div v-if="trainError" class="error-message">{{ trainError }}</div><button class="button button-primary full" :disabled="busy||!localReady||!trainForm.model||running(trainJob?.status)"><Icon name="play" :size="17" /> {{ busy?'正在提交…':'开始本地训练' }}</button></form><div class="stack"><article class="card run-panel"><div class="card-head"><div><span class="eyebrow">TRAINING MONITOR</span><h3>训练进度</h3></div><span v-if="trainJob" class="badge">{{ statusText(trainJob.status) }}</span></div><template v-if="trainJob"><p class="job-id">{{ trainJob.id }}</p><div class="progress-track"><span :style="{width:(trainJob.progress||0)+'%'}"></span></div><pre class="log-box">{{ (Array.isArray(trainJob.logs)?trainJob.logs.join('\n'):trainJob.logs)||'任务已提交，等待引擎输出…' }}</pre><p v-if="trainJob.error" class="error-message">{{ trainJob.error }}</p><button v-if="running(trainJob.status)" class="button button-outline" @click="cancelJob(trainJob)">停止任务</button></template><div v-else class="empty-state"><span><Icon name="train" :size="34" /></span><h4>下一次进步，始于一次训练</h4><p>配置参数并启动后，在这里查看真实日志与状态。</p><small>尚无正在运行的训练任务</small></div></article><article class="record-card"><span class="eyebrow">TRAINING ARCHIVE</span><h3>{{ trainingRun?'训练完成验证':'仓库训练记录' }}</h3><div><span>{{ trainingRun?.model||'YOLO11n' }} · {{ trainingRun?.epochs||10 }} epochs</span><b>{{ trainingRun?trainingPercent(trainingRun.metrics.map50):'90.95%' }} <small>mAP50</small></b></div><div v-if="trainingRun" class="archive-detail"><span>输入 {{ trainingRun.imgsz }} × {{ trainingRun.imgsz }} · Batch {{ trainingRun.batch }}</span><span>{{ (trainingRun.training_seconds/60).toFixed(2) }} 分钟 · {{ trainingRun.source_label }}</span></div></article></div></div><article v-if="trainingCurves.length" class="card training-archive-chart"><div class="card-head"><div><span class="eyebrow">LEARNING CURVE</span><h3>各轮验证指标</h3></div><span class="badge">{{ trainingRun.source_label }} · {{ trainingRun.epochs }} 轮</span></div><div class="training-curve-legend"><span><i></i>mAP50</span><span><i></i>mAP50–95</span><span>最后一轮 mAP50 {{ trainingPercent(trainingRun.last_epoch_metrics.map50) }}</span></div><svg viewBox="0 0 640 230" role="img" aria-label="同学训练记录中十轮验证集mAP变化曲线"><g v-for="v in [0,.25,.5,.75,1]" :key="v"><line x1="44" x2="604" :y1="195-v*155" :y2="195-v*155" class="curve-grid"/><text x="35" :y="199-v*155" text-anchor="end">{{ v*100 }}%</text></g><polyline :points="curvePoints('map50')" class="curve-map50"/><polyline :points="curvePoints('map50_95')" class="curve-map95"/><g v-for="r in trainingCurves" :key="r.epoch"><circle :cx="44+(r.epoch-1)/Math.max(trainingRun.epochs-1,1)*560" :cy="195-r.map50*155" r="3.5" class="curve-point"><title>第{{r.epoch}}轮 · mAP50 {{trainingPercent(r.map50)}}</title></circle><text :x="44+(r.epoch-1)/Math.max(trainingRun.epochs-1,1)*560" y="217" text-anchor="middle">{{r.epoch}}</text></g></svg><div class="training-archive-stats"><span>Precision <b>{{trainingPercent(trainingRun.metrics.precision)}}</b></span><span>Recall <b>{{trainingPercent(trainingRun.metrics.recall)}}</b></span><span>mAP50–95 <b>{{trainingPercent(trainingRun.metrics.map50_95)}}</b></span><span>Run <b>{{trainingRun.id}}</b></span></div></article></section>

        <section v-else-if="page==='inference'" class="page"><div class="page-title"><div><div class="eyebrow">UPLOAD. DETECT. UNDERSTAND.</div><h1>模型推理<span> / Inference</span></h1><p>把一段水下画面，转化为可检索、可解释的检测证据。</p></div><span class="badge"><i class="live-dot"></i> 本地 YOLO 推理</span></div><div v-if="!fishModels.length" class="notice model-config-note"><Icon name="fish" :size="19" /><span><b>{{ status?.model_configuration?.configured_weight?'已读取模型配置，权重文件待接入':'鱼类模型文件待接入' }}</b><small>{{ status?.model_configuration?.message||'项目使用本地鱼类 .pt 权重。当前还没有对应文件，接入后可开始真实识别。' }}</small></span><button @click="refresh">刷新</button></div><div class="inference-layout"><div class="stack"><article class="card"><div class="card-head"><div><span class="eyebrow">01 · INPUT</span><h3>上传检测素材</h3></div><span class="muted small">图片 / 视频</span></div><input ref="fileInput" type="file" hidden accept=".mp4,.mov,.avi,.mkv,.webm,.jpg,.jpeg,.png,.webp" @change="chooseFile($event.target.files[0])" /><button class="dropzone" :class="{dragging}" @click="fileInput.click()" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dragging=false;chooseFile($event.dataTransfer.files[0])"><span class="upload-symbol"><Icon name="upload" :size="28" /></span><h4>{{ file?file.name:'拖入画面，让识别开始' }}</h4><p>{{ file?`${(file.size/1048576).toFixed(1)} MB · 点击重新选择`:'点击选择文件，或拖拽到这里' }}</p><small>MP4 / MOV / AVI / MKV / WebM / JPG / PNG / WebP · 最大 250 MB</small></button><div v-if="file" class="input-preview"><video v-if="fileIsVideo" :src="filePreview" controls preload="metadata"></video><img v-else :src="filePreview" alt="待检测原始图片" /><span>原始输入 · 尚未检测</span></div><div class="privacy-note"><Icon name="check" :size="15" /> 原始视频留在本机；大模型仅接收结构化检测摘要。</div></article><form class="card" @submit.prevent="startInfer"><div class="card-head"><div><span class="eyebrow">02 · CONFIGURATION</span><h3>推理设置</h3></div><Icon name="scan" /></div><label>本地候选模型<select v-model="inferForm.model" required><option value="" disabled>选择候选权重 · 推理前核验33类标签</option><option v-for="m in fishModels" :value="m.id" :key="m.id">{{ m.name }}</option></select></label><label class="slider-label"><span>置信度阈值 <b>{{ Number(inferForm.conf).toFixed(2) }}</b></span><input v-model.number="inferForm.conf" type="range" min="0.05" max="0.95" step="0.05" :style="{'--range-progress':((Number(inferForm.conf)-.05)/.9*100)+'%'}" /></label><div class="form-row"><label>运行设备<select v-model="inferForm.device"><option value="cpu">CPU</option><option value="0">GPU 0 · 需 CUDA</option></select></label><label>视频采样间隔<select v-model.number="inferForm.stride"><option :value="1">每帧检测</option><option :value="2">每 2 帧</option><option :value="5">每 5 帧</option></select></label></div><details class="advanced"><summary>高级参数</summary><div class="form-row"><label>IoU 阈值<input v-model.number="inferForm.iou" type="number" min="0.1" max="0.95" step="0.05" /></label><label>输入尺寸<select v-model.number="inferForm.imgsz"><option :value="320">320</option><option :value="512">512</option><option :value="640">640</option><option :value="960">960</option></select></label></div></details><div v-if="inferError" class="error-message">{{ inferError }}</div><button class="button button-primary full" :disabled="busy||!file||!inferForm.model||running(inferJob?.status)"><Icon name="scan" :size="18" /> {{ busy?'正在上传…':'开始本地识别' }}</button></form></div><article class="card output-panel"><div class="card-head"><div><span class="eyebrow">03 · OBSERVATION</span><h3>识别结果</h3></div><span v-if="inferJob" class="badge">{{ statusText(inferJob.status) }}</span></div><div v-if="!inferJob" class="empty-state inference-empty"><span class="scan-empty"><Icon name="fish" :size="54" /></span><h4>等待第一次发现</h4><p>上传图片或视频，选择专用模型。<br>识别后的画面与类别统计将在这里呈现。</p><div class="empty-steps"><span>上传素材</span><i>→</i><span>本地检测</span><i>→</i><span>智能解释</span></div></div><template v-else><div v-if="running(inferJob.status)" class="processing-state"><div class="spinner"></div><h4>正在识别水下目标</h4><p>{{ inferJob.progress||0 }}% · 可继续浏览其他页面</p><div class="progress-track"><span :style="{width:(inferJob.progress||0)+'%'}"></span></div><button class="text-button" @click="cancelJob(inferJob)">取消任务</button></div><div v-if="inferJob.error" class="error-message">{{ inferJob.error }}</div><template v-if="inferResult"><div v-if="resultMedia" class="result-media"><video v-if="/\.(mp4|webm|mov)(\?|$)/i.test(resultMedia)" :src="resultMedia" controls></video><img v-else :src="resultMedia" alt="YOLO 真实检测标注结果" /></div><div class="result-summary"><div><span>检测到的类别</span><b>{{ resultCounts.length }} <small>类</small></b></div><div><span>检测框次</span><b>{{ formatNum(inferResult.total_detections||inferResult.summary?.total_detections||resultCounts.reduce((n,c)=>n+Number(c.count||0),0)) }}</b></div></div><div v-if="resultCounts.length" class="result-bars"><div v-for="c in resultCounts" :key="c.name"><span>{{ c.name }}</span><div><i :style="{width:(Number(c.count)/Math.max(...resultCounts.map(x=>Number(x.count)),1)*100)+'%'}"></i></div><b>{{ c.count }}</b></div></div><div v-if="resultCounts.length" class="table-scroll result-evidence"><table><thead><tr><th>类别</th><th>平均置信度</th><th>单帧峰值</th></tr></thead><tbody><tr v-for="c in resultCounts" :key="c.name"><td>{{ c.name }}</td><td>{{ c.mean_confidence!=null?(Number(c.mean_confidence)*100).toFixed(1)+'%':'—' }}</td><td>{{ c.peak_per_frame??'—' }}</td></tr></tbody></table></div><p class="muted small">{{ inferResult.counting_note||'统计为跨帧检测框次，同一条鱼可能重复出现，不代表独立个体数量。' }}</p><p class="muted small result-runtime">已分析 {{ inferResult.frames_analyzed||0 }} 帧 · 本地处理 {{ inferResult.processing_seconds||0 }} 秒</p><div class="result-actions"><button class="button button-primary" @click="explain"><Icon name="spark" :size="17" /> 交给助手解释</button><button class="button button-outline" @click="downloadReport"><Icon name="download" :size="17" /> 摘要报告</button><a v-if="inferResult.detections_url" class="text-button" :href="inferResult.detections_url" target="_blank" rel="noopener">逐帧证据 JSON <Icon name="link" :size="14" /></a></div></template><details v-if="inferJob.logs?.length" class="advanced"><summary>查看运行日志</summary><pre class="log-box">{{ Array.isArray(inferJob.logs)?inferJob.logs.join('\n'):inferJob.logs }}</pre></details></template></article></div></section>

        <section v-else-if="page==='dashboard'" class="page"><div class="page-title"><div><div class="eyebrow">EVERY EXPERIMENT LEAVES A TRACE</div><h1>监控仪表盘<span> / Dashboard</span></h1><p>实时查看本机资源、任务状态和实验记录。</p></div><button class="button button-outline" @click="refresh"><Icon name="refresh" :size="16" /> 刷新记录</button></div>
<article class="card live-monitor" aria-labelledby="monitor-heading">
  <div class="card-head monitor-heading"><div><span class="eyebrow">LIVE LOCAL MONITOR</span><h3 id="monitor-heading">本机运行监控</h3></div><span class="monitor-status" :class="{offline:monitorError}"><i></i>{{ monitorError?'连接中断':monitor?'实时监控中':'等待读数' }}</span></div>
  <p class="monitor-intro">真实读取当前电脑的资源使用情况，每 5 秒自动更新。</p>
  <div v-if="monitorError" class="error-message">{{ monitorError }}</div>
  <div class="resource-grid">
    <section class="resource-card resource-cpu"><div class="resource-label"><span><Icon name="train" :size="20" /> CPU 使用率</span><small>{{ monitor?.cpu?.logical_count!=null?monitor.cpu.logical_count+' 线程':'等待读数' }}</small></div><strong>{{ percentText(monitor?.cpu?.percent) }}<small v-if="monitor?.cpu?.percent!=null">%</small></strong><div class="resource-track"><i :style="{width:safePercent(monitor?.cpu?.percent)+'%'}"></i></div></section>
    <section class="resource-card resource-memory"><div class="resource-label"><span><Icon name="data" :size="20" /> 内存使用率</span><small>{{ monitor?.memory?memoryText(monitor.memory.used_bytes)+' / '+memoryText(monitor.memory.total_bytes):'等待读数' }}</small></div><strong>{{ percentText(monitor?.memory?.percent) }}<small v-if="monitor?.memory?.percent!=null">%</small></strong><div class="resource-track"><i :style="{width:safePercent(monitor?.memory?.percent)+'%'}"></i></div></section>
    <section class="resource-card resource-disk"><div class="resource-label"><span><Icon name="folder" :size="20" /> 项目磁盘使用率</span><small>{{ monitor?.disk?'可用 '+memoryText(monitor.disk.free_bytes):'等待读数' }}</small></div><strong>{{ percentText(monitor?.disk?.percent) }}<small v-if="monitor?.disk?.percent!=null">%</small></strong><div class="resource-track"><i :style="{width:safePercent(monitor?.disk?.percent)+'%'}"></i></div></section>
  </div>
  <div class="process-grid"><div><span>Web 进程</span><b>{{ monitor?.process?.pid!=null?'PID '+monitor.process.pid:'—' }}</b></div><div><span>连续运行</span><b>{{ uptimeText(monitor?.process?.uptime_seconds) }}</b></div><div><span>进程内存</span><b>{{ processMemoryText(monitor?.process?.rss_bytes) }}</b></div><div><span>GPU 状态</span><b>{{ monitor?.gpu?.available===true?(monitor.gpu.devices||[]).map(d=>d.name).join(' / '):monitor?.gpu?.message||'等待读数' }}</b></div></div>
  <div class="monitor-foot"><span>{{ monitorError?'上次成功采样：':'采样时间：' }}{{ lastMonitorSample?dateText(lastMonitorSample):'—' }}</span><span>{{ monitor?.runtime?.engine_available?'YOLO 引擎可用':monitor?'YOLO 引擎待准备':'连接本机服务后显示' }}</span></div>
  <p v-for="warning in monitor?.warnings||[]" :key="warning" class="muted small monitor-warning">{{ warning }}</p>
  <details class="monitor-logs"><summary>最近运行日志 <small>{{ monitor?.recent_jobs?.length||0 }} 个任务</small></summary><div v-if="!monitor?.recent_jobs?.length" class="muted small monitor-log-empty">尚无任务日志，训练或推理后会在这里更新。</div><article v-for="job in monitor?.recent_jobs||[]" :key="job.id" class="monitor-log-item"><div><b>{{ job.type==='train'?'模型训练':'模型推理' }}</b><span>{{ statusText(job.status) }}</span><small>{{ dateText(job.updated_at) }}</small></div><p v-if="job.error" class="error-message">{{ job.error }}</p><pre v-if="job.latest_logs?.length">{{ job.latest_logs.join('\n') }}</pre><p v-else class="muted small">暂无运行日志</p></article></details>
</article>
<div class="metric-grid"><article class="plain-metric"><span>本机候选权重</span><strong>{{ fishModels.length }}<small>个</small></strong></article><article class="plain-metric"><span>已完成任务</span><strong>{{ monitor?.jobs?.completed??completedJobs.length }}<small>次</small></strong></article><article class="plain-metric"><span>运行中任务</span><strong>{{ monitor?.jobs?.running!=null?monitor.jobs.running+Number(monitor.jobs.queued||0):jobs.filter(j=>running(j.status)).length }}<small>个</small></strong></article><article class="plain-metric"><span>可用实验记录</span><strong>{{ actualExperiments.length }}<small>份</small></strong></article></div><div class="two-col"><article class="card"><div class="card-head"><div><span class="eyebrow">REPOSITORY EVALUATION RECORD</span><h3>独立验证集评估</h3></div><span class="badge">YOLO11n</span></div><div class="evaluation-bars"><div v-for="m in [{name:'mAP@50',v:90.73},{name:'mAP@50–95',v:74.42},{name:'Precision',v:82.68},{name:'Recall',v:88.74}]" :key="m.name"><span>{{ m.name }}</span><div><i :style="{width:m.v+'%'}"></i></div><b>{{ m.v.toFixed(2) }}<small>%</small></b></div></div></article><article class="card"><div class="card-head"><div><span class="eyebrow">LOCAL ENVIRONMENT</span><h3>工作空间状态</h3></div><Icon name="data" /></div><div class="environment-row"><span>平台引擎</span><b>{{ engineReady?'可用':'待准备' }}</b></div><div class="environment-row"><span>鱼类数据</span><b>{{ localReady?'已接入':'未接入' }}</b></div><div class="environment-row"><span>候选模型权重</span><b>{{ fishModels.length?`${fishModels.length} 个待核验`:'未接入' }}</b></div><div class="environment-row"><span>智能解释</span><b>{{ status?.llm?.configured?'大模型已配置':'本地规则解释' }}</b></div><p class="muted small">记录仅来自当前本机工作空间。刷新可读取最新文件与任务状态。</p></article></div><article class="card"><div class="card-head"><div><span class="eyebrow">RECENT ACTIVITY</span><h3>任务记录</h3></div><span class="muted small">{{ jobs.length }} 条</span></div><div v-if="!jobs.length" class="empty-state compact"><span><Icon name="clock" :size="30" /></span><h4>这里将记录你的研究足迹</h4><p>完成一次训练或推理后，任务状态会出现在这里。</p></div><div v-else class="table-scroll"><table><thead><tr><th>任务 ID</th><th>类型</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id"><td class="mono">{{ j.id }}</td><td>{{ j.type==='train'?'模型训练':'模型推理' }}</td><td><span class="status-chip" :class="j.status">{{ statusText(j.status) }}</span></td><td>{{ dateText(j.created_at) }}</td><td><button class="text-button" @click="j.type==='train'?(trainJob=j,go('training')):(inferJob=j,go('inference'))">查看</button></td></tr></tbody></table></div></article><article v-if="actualExperiments.length" class="card"><div class="card-head"><h3>实验记录</h3></div><div class="table-scroll"><table><thead><tr><th>运行编号</th><th>来源</th><th>mAP50</th><th>mAP50–95</th><th>Precision</th><th>Recall</th></tr></thead><tbody><tr v-for="e in actualExperiments" :key="e.id"><td class="mono">{{e.id}}</td><td>{{e.provenance==='provided_training_archive'?'同学训练记录':e.kind==='evaluation'?'本机评估':'本机训练'}}</td><td>{{experimentMetric(e,'map50')}}</td><td>{{experimentMetric(e,'map50_95')}}</td><td>{{experimentMetric(e,'precision')}}</td><td>{{experimentMetric(e,'recall')}}</td></tr></tbody></table></div></article></section>

        <section v-else-if="page==='assistant'" class="page assistant-page"><div class="page-title"><div><div class="eyebrow">TURN OBSERVATIONS INTO INSIGHT</div><h1>渔见助手<span> / AI Assistant</span></h1><p>让每一个检测结果，都有更容易理解的答案。</p></div><span class="badge"><i class="live-dot"></i>{{ status?.llm?.configured?'大模型已配置':'本地规则解释模式' }}</span></div><div class="assistant-layout"><article class="card chat-panel"><div class="chat-top"><span class="assistant-avatar"><Icon name="spark" :size="22" /></span><div><b>渔见研究助手</b><small>基于项目上下文与检测证据回答</small></div><span class="chat-mode">{{ chatMode==='llm'?'LLM':status?.llm?.configured?'LLM READY':'LOCAL' }}</span></div><div ref="messageList" class="messages"><div v-for="(m,i) in messages" :key="i" class="message" :class="m.role"><span class="message-avatar"><Icon v-if="m.role==='assistant'" name="fish" :size="19" /><template v-else>我</template></span><div><span class="message-author">{{ m.role==='assistant'?'渔见助手':'你' }} <small v-if="m.mode">{{ m.mode==='llm'?'大模型回答':'本地规则解释' }}</small></span><div class="message-content">{{ m.content }}</div><small v-if="m.disclosure" class="message-disclosure">{{ m.disclosure }}</small></div></div><div v-if="chatBusy" class="message assistant"><span class="message-avatar"><Icon name="fish" :size="19" /></span><div class="typing"><i></i><i></i><i></i><span>正在整理回答…</span></div></div></div><div v-if="messages.length===1" class="prompt-grid"><button v-for="p in prompts" :key="p" @click="sendChat(p)">{{ p }}<Icon name="arrow" :size="14" /></button></div><div v-if="chatError" class="error-message">{{ chatError }}</div><form class="chat-form" @submit.prevent="sendChat()"><textarea v-model="question" rows="2" placeholder="问问数据、训练，或这次视频识别结果…" aria-label="输入问题" @keydown.enter.exact.prevent="sendChat()"></textarea><button class="send-button" aria-label="发送问题" :disabled="chatBusy||!question.trim()"><Icon name="arrow" :size="20" /></button></form><div class="chat-footer">{{ status?.llm?.configured?'仅将文本上下文与结构化检测证据发送至配置的大模型服务。':'尚未配置 API，使用本地规则生成说明；不代表大模型已调用。' }}</div></article><aside class="stack"><article class="card evidence-card"><span class="eyebrow">EVIDENCE IN CONTEXT</span><h3>本次检测上下文</h3><template v-if="inferResult"><span class="context-badge"><Icon name="check" :size="15" /> 已关联真实推理</span><p class="mono small">{{ inferJob.id }}</p><p>{{ resultCounts.length }} 个类别 · {{ formatNum(resultCounts.reduce((n,c)=>n+Number(c.count||0),0)) }} 框次</p><button class="text-button" @click="go('inference')">返回查看结果 <Icon name="arrow" :size="15" /></button></template><template v-else><div class="context-empty"><Icon name="scan" :size="30" /><p>尚未关联检测任务</p><small>先完成一次本地推理，即可围绕真实结果提问。</small></div><button class="button button-outline full" @click="go('inference')">前往识别 <Icon name="arrow" :size="16" /></button></template></article><article class="assistant-note"><Icon name="help" :size="20" /><h4>有依据，也有边界</h4><p>助手可以解释识别类别、置信度与检测数量。它不会仅凭检测框推断鱼的健康、精确体重或水质。</p><p>跨帧框次不等于独立个体数量，低置信度结果建议人工复核。</p></article></aside></div></section>

        <footer class="footer"><span><Icon name="fish" :size="17" /> 渔见 FISH SCOPE</span><span>Built on ODPlatform · 让视觉识别更易理解</span><span>本地研究工作空间 <i></i></span></footer>
      </main>
    </div>
    <div v-if="guide" class="modal-backdrop" @click.self="guide=false"><section class="guide-modal" role="dialog" aria-modal="true" aria-labelledby="guide-title"><button class="modal-close icon-button" aria-label="关闭指南" @click="guide=false"><Icon name="close" /></button><span class="eyebrow">GET STARTED WITH FISH SCOPE</span><h2 id="guide-title">让你的工作空间准备就绪</h2><p class="muted">网页已连接现有目标检测平台。接入本地资源后，即可运行真实任务。</p><ol class="guide-steps"><li><b>接入鱼类数据</b><p>使用平台转换与质检命令，生成 data/processed/fish 与 fish.yaml。</p></li><li><b>放入专用模型</b><p>将训练后的鱼类 .pt 权重放入 models/trained。通用 COCO 模型不作为鱼类模型使用。</p></li><li><b>配置智能解释（可选）</b><p>后端环境变量 FISH_LLM_BASE_URL、FISH_LLM_API_KEY、FISH_LLM_MODEL；未配置时使用明确标注的本地规则解释。</p></li><li><b>上传视频并识别</b><p>进入模型推理页，上传素材、选择模型，然后将结构化结果交给智能助手。</p></li></ol><div class="modal-bottom"><span>Gradio 使用 odp-demo 单独启动。</span><button class="button button-primary" @click="guide=false;go('inference')">进入工作空间 <Icon name="arrow" :size="16" /></button></div></section></div>
  </div>
</template>
